  "indicator_readings": [
    {
      "indicator": "Preço (close)",
      "reading": "40.18",
      "interpretation": "Fechamento abaixo da MM20 e das EMAs; pullback, próximo suporte em BB_lower 40.01."
    },
    {
      "indicator": "MM20",
      "reading": "41.7380",
      "interpretation": "Média curta acima das demais (MM20>MM50>MM200) — tendência de fundo altista; atua como resistência de curto prazo."
    },
    {
      "indicator": "MM50",
      "reading": "39.5410",
      "interpretation": "Suporte de médio prazo — preço ainda acima da MM50, mantendo o viés de fundo."
    },
    {
      "indicator": "MM200",
      "reading": "33.9747",
      "interpretation": "Suporte estrutural de longo prazo; tendência secular permanece positiva enquanto preço estiver distante acima."
    },
    {
      "indicator": "EMA9",
      "reading": "41.2813",
      "interpretation": "EMA9 acima do preço — pressão de venda no curtíssimo prazo; resistência imediata."
    },
    {
      "indicator": "EMA21",
      "reading": "41.1649",
      "interpretation": "EMA21 acima do preço e próxima da EMA9 — confirma enfraquecimento de curto prazo."
    },
    {
      "indicator": "MACD",
      "reading": "0.4355",
      "interpretation": "MACD positivo mas abaixo da linha de sinal (0.8332) — momentum de alta desacelerando."
    },
    {
      "indicator": "MACD_signal",
      "reading": "0.8332",
      "interpretation": "Linha de sinal acima do MACD — sinal de correção no curto prazo."
    },
    {
      "indicator": "MACD_hist",
      "reading": "-0.3977",
