    },
    {
      "indicator": "BB_lower",
      "reading": "40.0145",
      "interpretation": "Banda inferior próxima ao preço — suporte imediato e possível área de rejeição."
    },
    {
      "indicator": "BB_mid",
      "reading": "41.7380",
      "interpretation": "Banda média = MM20; atualmente acima do preço e funcionando como resistência."
    },
    {
      "indicator": "BB_upper",
      "reading": "43.4615",
      "interpretation": "Resistência superior da banda — marca teto da volatilidade recente."
    },
    {
      "indicator": "RSI14",
      "reading": "44.5468",
